// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeSubjectEdition = function (meta, rows) {
  const {subject, year, grade, contest, letters, tasksFile, answersFile, language} = meta;
  const folder = 'assets/' + subject + '/' + year + '/';
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(row => {
    const {title, question, choices, figure, optionFigures, steps, context, audio, numericAnswer} = row;
    const options = choices.map((text, i) => {
      const image = optionFigures?.[i];
      if (!image) return {text};
      return {text: row.showOptionText ? text : '', image: image.src,
        description: row.showOptionText ? text + '. ' + image.alt : image.alt,
        ...(image.detailSrc ? {detailSrc: image.detailSrc} : {}),
        pixelWidth: image.width, pixelHeight: image.height};
    });
    return {
      title, question, choices, language, context, guided: true, hideIntroText: true,
      skill: contest, answer: row.answer ?? null, points: row.points ?? meta.points,
      ...(Number.isInteger(numericAnswer) ? {numericAnswer, questionNote: 'В тренировочном рейтинге за эту задачу баллы не начисляются.'} : {}),
      ...(audio ? {audio: folder + 'listening.mp3'} : {}),
      ...(figure || optionFigures ? {choiceLayout: {condition: figure, options},
        choiceImages: options.map(option => option.image),
        ...(figure ? {conditionImage: figure.src, conditionAlt: figure.alt} : {})} : {}),
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ...steps.map((explanation, index) => index === steps.length - 1
          ? ['Проверка', 'Проверка', explanation]
          : [index ? 'Шаг ' + (index + 1) : 'Первый шаг', 'Рассуждение', explanation]),
        ['Ответ', 'Ответ', ''],
      ],
    };
  });
  return {
    id: year + '-' + subject + '-' + grade, year, grades, label: grades.join('–') + ' классы',
    ...(meta.sections ? {sections: meta.sections} : {}),
    ...(meta.titleLanguage ? {titleLanguage: meta.titleLanguage} : {}),
    subject, answerLetters: [...letters], sources: {
      contest, tasksUrl: folder + tasksFile, answersUrl: folder + answersFile,
      ...(meta.reviewedKey ? {reviewedKey: true} : {}),
    },
    lessons, scenes: lessons.map(() => () => ''),
  };
};

register(globalThis.makeSubjectEdition({"subject":"british-bulldog","year":2025,"grade":"3-4","contest":"British Bulldog","letters":"ABCD","count":35,"language":"en","points":3,"tasksFile":"tasks.pdf","answersFile":"answers.pdf","sections":[{"start":1,"title":"Listening"},{"start":6,"title":"Reading"},{"start":11,"title":"Verb forms"},{"start":16,"title":"Holiday pictures"},{"start":21,"title":"Parts of a house"},{"start":26,"title":"Grammar"},{"start":31,"title":"Telling the time"}],"titleLanguage":"en"}, [{"title":"What She’s Doing","question":"What is the woman doing at the moment? She is ... .","context":"Listen to the recording and answer the questions","choices":["cooking","drinking","eating","sleeping"],"answer":0,"steps":["Вопрос «What is the woman doing at the moment?» означает «Что женщина делает сейчас?» Ищи её ответ на вопрос о том, что она делает.","Женщина отвечает «I’m making a cake», то есть она печёт торт. Приготовление еды по-английски — cooking."],"audio":true},{"title":"The Cake’s Flavour","question":"What kind of cake is the woman baking?","context":"Listen to the recording and answer the questions","choices":["Chocolate and banana","Strawberry and banana","Strawberry and cherry","Strawberry and chocolate"],"answer":2,"steps":["Найди в реплике женщины названия двух ягод рядом со словом cake — «торт».","Женщина говорит «a strawberry and cherry cake». Strawberry означает «клубника», а cherry — «вишня»."],"audio":true},{"title":"Who the Cake Is For","question":"The woman is baking a cake for ... .","context":"Listen to the recording and answer the questions","choices":["her friends","her husband","herself","her children"],"answer":2,"steps":["Слово for помогает понять, кому предназначен торт. Послушай, что женщина говорит сразу после названия торта.","Она говорит «for me to eat», то есть собирается съесть торт сама. Поэтому про неё говорим «She is baking a cake for herself»."],"audio":true},{"title":"The Man’s Offer","question":"What does the man offer to eat?","context":"Listen to the recording and answer the questions","choices":["A cherry toast","Strawberry jam","A ham sandwich","Chocolate butter"],"answer":2,"steps":["Найди предложение, которое начинается с «Do you want …?» Так мужчина спрашивает, хочет ли женщина что-нибудь съесть.","Мужчина спрашивает «Do you want a ham sandwich?» Ham означает «ветчина». Он предлагает бутерброд с ветчиной."],"audio":true},{"title":"The Woman’s Request","question":"What kind of sandwich does the woman ask for?","context":"Listen to the recording and answer the questions","choices":["Chocolate","Banana","Peanut butter","Chicken"],"answer":1,"steps":["Женщина начинает просьбу словами «Can I have …?» Это значит «Можно мне …?» Послушай, что она называет дальше.","Она спрашивает «Can I have a banana sandwich, please?» Значит, её просьба — бутерброд с бананом."],"audio":true},{"title":"Cities in Great Britain","question":"The largest city in Great Britain is ... .","context":"Read the text and choose the right variant\n\nLondon is the capital of Great Britain. There are more than 10 million people living here. It is the largest city in the country. The Thames flows through it. It provides 2/3 of London’s drinking water. Traditionally, the capital is divided into several parts: the City, the West End, the East End and Westminster. It has one of the largest airports in the world, named Heathrow. London’s most famous sights are red double-decker buses, The Houses of Parliament, St Paul’s Cathedral, The Tower of London and many more.","choices":["Liverpool","London","Oxford","Manchester"],"answer":1,"steps":["Найди предложение «It is the largest city in the country». Выражение the largest city означает «самый большой город».","Местоимение it относится к Лондону, о котором говорится с начала абзаца. Выбираем London."]},{"title":"A London Waterway","question":"The name of the most famous waterway in London is ... .","context":"Read the text and choose the right variant\n\nLondon is the capital of Great Britain. There are more than 10 million people living here. It is the largest city in the country. The Thames flows through it. It provides 2/3 of London’s drinking water. Traditionally, the capital is divided into several parts: the City, the West End, the East End and Westminster. It has one of the largest airports in the world, named Heathrow. London’s most famous sights are red double-decker buses, The Houses of Parliament, St Paul’s Cathedral, The Tower of London and many more.","choices":["the Wye","the Trent","the Thames","the Severn"],"answer":2,"steps":["Waterway означает «водный путь». Ищи в тексте предложение о реке, которая протекает через город.","В предложении «The Thames flows through it» названа Темза. По-английски это the Thames."]},{"title":"Parts of London","question":"There are ... parts in London.","context":"Read the text and choose the right variant\n\nLondon is the capital of Great Britain. There are more than 10 million people living here. It is the largest city in the country. The Thames flows through it. It provides 2/3 of London’s drinking water. Traditionally, the capital is divided into several parts: the City, the West End, the East End and Westminster. It has one of the largest airports in the world, named Heathrow. London’s most famous sights are red double-decker buses, The Houses of Parliament, St Paul’s Cathedral, The Tower of London and many more.","choices":["2","3","4","5"],"answer":2,"steps":["Ищи фразу «the capital is divided into several parts». После неё автор перечисляет части города.","Посчитай названия. The City, the West End, the East End и Westminster — четыре части."]},{"title":"A London Airport","question":"The name of the main airport in London is ... .","context":"Read the text and choose the right variant\n\nLondon is the capital of Great Britain. There are more than 10 million people living here. It is the largest city in the country. The Thames flows through it. It provides 2/3 of London’s drinking water. Traditionally, the capital is divided into several parts: the City, the West End, the East End and Westminster. It has one of the largest airports in the world, named Heathrow. London’s most famous sights are red double-decker buses, The Houses of Parliament, St Paul’s Cathedral, The Tower of London and many more.","choices":["Thames","Tower","Heathrow","Greater London"],"answer":2,"steps":["В тексте нужно найти слово airports. Слово named рядом с ним означает «под названием».","Автор пишет «named Heathrow». Значит, лондонский аэропорт называется Heathrow."]},{"title":"Getting Around London","question":"One of the famous means of transport in London is ... .","context":"Read the text and choose the right variant\n\nLondon is the capital of Great Britain. There are more than 10 million people living here. It is the largest city in the country. The Thames flows through it. It provides 2/3 of London’s drinking water. Traditionally, the capital is divided into several parts: the City, the West End, the East End and Westminster. It has one of the largest airports in the world, named Heathrow. London’s most famous sights are red double-decker buses, The Houses of Parliament, St Paul’s Cathedral, The Tower of London and many more.","choices":["a red bus","a green tram","a pink cab","a yellow train"],"answer":0,"steps":["Means of transport означает «вид транспорта». Найди транспорт в последнем предложении, где перечислены известные достопримечательности.","Red double-decker buses — это красные двухэтажные автобусы. В вариантах им соответствует a red bus."]},{"title":"Jane’s Little Puppy","question":"Jane’s little puppy ... very funny.","context":"Find the right verb form","choices":["have","are","were","is"],"answer":3,"steps":["Речь об одном щенке. Вместо Jane’s little puppy можно поставить it.","Чтобы связать it и описание very funny, в настоящем времени нужна форма to be — is. Получаем «Jane’s little puppy is very funny»."]},{"title":"A Hungry Puppy","question":"When Jane’s puppy is hungry, it ... “bow-wow”.","context":"Find the right verb form","choices":["said","told","speak","says"],"answer":3,"steps":["Речь о том, что щенок делает всякий раз, когда голоден. Для повторяющегося действия подходит Present Simple.","Подлежащее it требует окончания -s. Получаем it says “bow-wow” — щенок говорит «гав-гав»."]},{"title":"The Boys’ Hockey Game","question":"The boys ... hockey now, because they don’t have any homework.","context":"Find the right verb form","choices":["playing","are playing","plays","played"],"answer":1,"steps":["Слово now показывает, что мальчики играют прямо сейчас. Для такого действия нужен Present Continuous.","С подлежащим the boys во множественном числе берём are и прибавляем playing. Получается «The boys are playing hockey now»."]},{"title":"The Dog and the Water","question":"The dog ... the water and went to sleep on the rag.","context":"Find the right verb form","choices":["drank","drinks","is drinking","drinked"],"answer":0,"steps":["Went — прошедшая форма глагола go. Собака сначала попила, затем пошла спать. Оба действия уже произошли.","Drink — неправильный глагол. В Past Simple он принимает форму drank."]},{"title":"Elizabeth’s Pets","question":"Elizabeth ... a pet a year ago, but now she has got a turtle and a cat.","context":"Find the right verb form","choices":["have not","didn’t has","didn’t have","have"],"answer":2,"steps":["A year ago означает «год назад». Союз but показывает, что теперь у Элизабет питомцы есть, а тогда их не было.","Отрицание в Past Simple строится с didn’t. После него ставим начальную форму глагола have и получаем didn’t have."]},{"title":"An Orange Greeting Card","question":"What holiday is it?","choices":["Halloween","Thanksgiving Day","Shrovetide","Easter"],"answer":0,"steps":["Jack-o’-lantern — фонарь из тыквы с вырезанным лицом. Ghost и witch — привидение и ведьма.","Тыквенный фонарь и костюмы привидений и ведьм — привычные символы праздника Halloween."],"figure":{"src":"assets/british-bulldog/2025/holiday-16.webp","alt":"Оранжевая открытка с тыквой и летучими мышами. На ней написано «Spider», «Jack-o’-lantern», «Ghost», «Witch» и «TRICK OR TREAT PARTY».","width":303,"height":204}},{"title":"An Autumn Greeting Card","question":"What holiday is it?","choices":["Fool’s Day","Thanksgiving Day","New Year’s Day","Discovery of America"],"answer":1,"steps":["На открытке нарисована индейка, а pumpkin pie означает «тыквенный пирог». Корабль Mayflower привёз английских поселенцев, которые основали Плимутскую колонию.","Тыквенный пирог и индейка — традиционные блюда ко Дню благодарения. Название праздника в ответах — Thanksgiving Day."],"figure":{"src":"assets/british-bulldog/2025/holiday-17.webp","alt":"Открытка с индейкой, тыквами и осенними листьями. На ней написано «Mayflower ship», «Pumpkin pie», «Pilgrim hats» и «Fall Leaves».","width":303,"height":204}},{"title":"Gifts on a Card","question":"What holiday is it?","choices":["Christmas","Easter","Shrovetide","Thanksgiving Day"],"answer":0,"steps":["Reindeer — северный олень, presents — подарки. На картинке также видны наряженная ёлка и Санта-Клаус.","Санта-Клаус с подарками и оленями связан с Рождеством. По-английски это Christmas."],"figure":{"src":"assets/british-bulldog/2025/holiday-18.webp","alt":"Зимняя открытка с ёлкой, подарками и Сантой. На ней написано «SEASON GREETING», «Reindeer», «Presents», «Gingerbread» и «Bells».","width":212,"height":313}},{"title":"A Patterned Card","question":"What holiday is it?","choices":["Easter","St. Valentine’s Day","Halloween","New Year’s Day"],"answer":1,"steps":["Hearts и roses означают «сердца» и «розы». Cupid — Купидон, персонаж с луком и стрелами, символ любви.","Сердечки, розы и Купидон встречаются на валентинках. Это подсказки ко Дню святого Валентина — St. Valentine’s Day."],"figure":{"src":"assets/british-bulldog/2025/holiday-19.webp","alt":"Открытка с сердечками и Купидоном. На ней написано «Cupid», «Dove», «Hearts» и «Roses».","width":212,"height":313}},{"title":"A Card with Balloons","question":"What holiday is it?","choices":["Mother’s Day","Fool’s Day","Father’s Day","Halloween"],"answer":1,"steps":["Jokes — шутки, а to prank и to fool означают «разыгрывать» и «дурачить».","Первого апреля принято шутить и разыгрывать друг друга. Этот праздник в вариантах назван Fool’s Day."],"figure":{"src":"assets/british-bulldog/2025/holiday-20.webp","alt":"Открытка с шариками и шутовским колпаком. На ней написано «Jokes», «To prank», «Cuckoo» и «To fool».","width":212,"height":313}},{"title":"A House in Bad Weather","question":"It protects the house from rain, hail and snow.","context":"Look at the picture of the house and make a choice","choices":["Roof","Floor","Chimney","Stairs"],"answer":0,"steps":["Rain, hail and snow — дождь, град и снег. Ищи часть дома вверху, на которую они попадают.","На рисунке скатная крыша закрывает дом сверху. Крыша по-английски — roof."],"figure":{"src":"assets/british-bulldog/2025/house.webp","alt":"Дом со скатной крышей, дымовой трубой и окнами. Дорожка ведёт к крыльцу и входной двери, слева от неё видны широкие ворота.","width":655,"height":530}},{"title":"A Place for the Car","question":"You can keep your car there.","context":"Look at the picture of the house and make a choice","choices":["Balcony","Garage","Attic","Cellar"],"answer":1,"steps":["Car означает «машина». На рисунке слева от крыльца есть широкие ворота, через которые машина может въехать.","За такими воротами находится гараж — по-английски garage."],"figure":{"src":"assets/british-bulldog/2025/house.webp","alt":"Дом со скатной крышей, дымовой трубой и окнами. Дорожка ведёт к крыльцу и входной двери, слева от неё видны широкие ворота.","width":655,"height":530}},{"title":"Entering the House","question":"It’s the entrance to the house.","context":"Look at the picture of the house and make a choice","choices":["Window","Door","Chimney","Roof"],"answer":1,"steps":["Entrance означает «вход». На рисунке ступеньки ведут ко входу под навесом.","Чтобы войти в дом, открывают дверь. В ответах она называется door."],"figure":{"src":"assets/british-bulldog/2025/house.webp","alt":"Дом со скатной крышей, дымовой трубой и окнами. Дорожка ведёт к крыльцу и входной двери, слева от неё видны широкие ворота.","width":655,"height":530}},{"title":"Looking Outside","question":"You can see the sky, the clouds and the sun through it.","context":"Look at the picture of the house and make a choice","choices":["Window","Wall","Cellar","Chimney"],"answer":0,"steps":["Фраза see ... through it означает «видеть ... через это». Ищи часть дома со стеклом, через которую видно небо.","Через стекло окна можно смотреть на улицу. Окно по-английски — window."],"figure":{"src":"assets/british-bulldog/2025/house.webp","alt":"Дом со скатной крышей, дымовой трубой и окнами. Дорожка ведёт к крыльцу и входной двери, слева от неё видны широкие ворота.","width":655,"height":530}},{"title":"The Way to the House","question":"It’s the road towards the house.","context":"Look at the picture of the house and make a choice","choices":["Garden","Gates","Roof","Path"],"answer":3,"steps":["Towards the house означает «по направлению к дому». Посмотри, что ведёт через газон к крыльцу.","Небольшая дорожка, по которой можно подойти к дому, по-английски называется path."],"figure":{"src":"assets/british-bulldog/2025/house.webp","alt":"Дом со скатной крышей, дымовой трубой и окнами. Дорожка ведёт к крыльцу и входной двери, слева от неё видны широкие ворота.","width":655,"height":530}},{"title":"His Father at the Bank","question":"His father ... in a bank.","context":"Fill in the blanks","choices":["work","works","working","are working"],"answer":1,"steps":["Это сообщение о месте работы. Для постоянной работы здесь подходит Present Simple.","His father можно заменить на he. После he к work добавляем -s и получаем works."]},{"title":"The Boy’s English","question":"The boy ... speak English.","context":"Fill in the blanks","choices":["can","can to","cans","to can"],"answer":0,"steps":["Нужно выразить умение говорить по-английски. Для этого используется модальный глагол can.","Форма can одинакова для всех лиц. Сразу после неё ставим speak без to. Получаем «The boy can speak English»."]},{"title":"A Brother and a Sister","question":"His sister and his brother ... students.","context":"Fill in the blanks","choices":["am","is","are","was"],"answer":2,"steps":["Сестру и брата вместе можно заменить местоимением they, потому что речь о двух людях.","С they форма глагола to be в настоящем времени — are. Получаем «His sister and his brother are students»."]},{"title":"Three out of Ten","question":"Only three ... out of ten are grey.","context":"Fill in the blanks","choices":["gooses","goose","geese","geeses"],"answer":2,"steps":["После three нужно существительное во множественном числе. Goose означает «гусь».","У goose неправильное множественное число. Гласные меняются, и получается geese — «гуси»."]},{"title":"A Birthday Question","question":"... is his birthday?","context":"Fill in the blanks","choices":["When","What","Why","Who"],"answer":0,"steps":["О дне рождения естественно спросить, в какой день он бывает. Нужное вопросительное слово запрашивает время или дату.","When означает «когда». «When is his birthday?» переводится «Когда у него день рождения?»"]},{"title":"Five Minutes on the Clock","question":"It’s 5 minutes ... .","context":"What time is it?","choices":["past 12","to 12","past 1","to 1"],"answer":0,"steps":["Длинная стрелка на 1 показывает пять минут. Короткая у 12 показывает, что двенадцать уже пробило.","Past означает «после» названного часа. 12:05 — это five minutes past twelve."],"figure":{"src":"assets/british-bulldog/2025/clock-31.webp","alt":"На циферблате длинная стрелка на 1, короткая — у 12.","width":142,"height":142}},{"title":"Hours and Minutes","question":"It’s ... .","context":"What time is it?","choices":["a quarter to 2","half past 1","a quarter past 2","a quarter past 1"],"answer":3,"steps":["Минутная стрелка у 3 показывает 15 минут. Часовая уже прошла 1, поэтому на часах 1:15.","15 минут — четверть часа, a quarter. Четверть после часа по-английски — a quarter past one."],"figure":{"src":"assets/british-bulldog/2025/clock-32.webp","alt":"На циферблате длинная стрелка на 3, короткая — чуть дальше 1.","width":142,"height":142}},{"title":"Ten Minutes on the Clock","question":"It’s 10 minutes ... .","context":"What time is it?","choices":["past 11","to 11","past 10","to 10"],"answer":2,"steps":["Длинная стрелка на 2 показывает 10 минут. Короткая стрелка только прошла отметку 10.","На часах 10:10, то есть десять минут после десяти. По-английски это ten minutes past ten."],"figure":{"src":"assets/british-bulldog/2025/clock-33.webp","alt":"На циферблате длинная стрелка на 2, короткая — у 10.","width":142,"height":142}},{"title":"Where the Hands Point","question":"It’s ... .","context":"What time is it?","choices":["half past 2","20 minutes to 2","half past 1","20 minutes to 1"],"answer":1,"steps":["Длинная стрелка на 8 показывает 40 минут. Короткая между 1 и 2, поэтому время — 1:40.","До двух часов остаётся 60 − 40 = 20 минут. «Без двадцати два» по-английски — twenty minutes to two."],"figure":{"src":"assets/british-bulldog/2025/clock-34.webp","alt":"На циферблате длинная стрелка на 8, короткая — между 1 и 2 ближе к 2.","width":142,"height":142}},{"title":"The Hands on the Dial","question":"It’s ... .","context":"What time is it?","choices":["three o’clock","two o’clock sharp","one o’clock","about two o’clock"],"answer":1,"steps":["Длинная стрелка у 12 означает ноль минут, короткая у 2 показывает час. На часах ровно 2:00.","Слово sharp подчёркивает точное время. «Ровно два» — two o’clock sharp."],"figure":{"src":"assets/british-bulldog/2025/clock-35.webp","alt":"На циферблате длинная стрелка на 12, короткая — на 2.","width":142,"height":142}}]), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
